const { native } = require('./config/_import.js')

function constructPerson () {
  /*
    $lb(empty,Van De Griek,Dmitry N.,976-76-7082,46614,$lb(1765 Second Place,Fargo,NE,29498),$lb(3349 Oak Court,Gansevoort,NY,75517),empty,$lb(Red))
  */
  const home = constructAddress({
    street: '1765 Second Place',
    city: 'Fargo',
    state: 'NE',
    zip: 29498
  })

  const office = constructAddress({
    street: '3349 Oak Court',
    city: 'Gansevoort',
    state: 'NY',
    zip: 75517
  })

  const favorites = new native.IRISList()
  favorites.add('red')
  favorites.add('fucia')

  const person = new native.IRISList()
  person.add(null)
  person.add('Van De Griek,Dmitry N.')
  person.add('976-76-7082')
  person.add(46614)
  person.add(home)
  person.add(office)
  person.add(null)
  person.add(favorites)
  return person
}

function constructAddress (data) {
  const address = new native.IRISList()
  address.add(data.street)
  address.add(data.city)
  address.add(data.state)
  address.add(data.zip)
  return address
}

